function handlePresentationRoute(req, res, path, deps) {
  const method = req.method ?? "GET";
  if (path === "/api/presentation/status") {
    if (method !== "GET" && method !== "HEAD") {
      res.setHeader("Allow", "GET");
      sendJson3(res, 405, { error: "m\xE9todo n\xE3o permitido" });
      return true;
    }
    sendJson3(res, 200, getPresentationStatus());
    return true;
  }
  if (path === "/api/presentation/summon") {
    if (method !== "POST") {
      res.setHeader("Allow", "POST");
      sendJson3(res, 405, { error: "m\xE9todo n\xE3o permitido" });
      return true;
    }
    void readJsonBody(req).then((body2) => {
      const title = typeof body2?.title === "string" ? body2.title : void 0;
      setPendingReview(true, title);
      sendJson3(res, 200, { ok: true, status: getPresentationStatus() });
    }).catch(() => {
      setPendingReview(true);
      sendJson3(res, 200, { ok: true, status: getPresentationStatus() });
    });
    return true;
  }
  if (path === "/api/presentation/deck") {
    if (method !== "GET" && method !== "HEAD") {
      res.setHeader("Allow", "GET");
      sendJson3(res, 405, { error: "m\xE9todo n\xE3o permitido" });
      return true;
    }
    const deck = buildPresentationDeck(deps);
    sendJson3(res, 200, deck);
    return true;
  }
  if (path.startsWith("/api/presentation/media/")) {
    if (method !== "GET" && method !== "HEAD") {
      res.setHeader("Allow", "GET");
      sendJson3(res, 405, { error: "m\xE9todo n\xE3o permitido" });
      return true;
    }
    const key = decodeURIComponent(path.slice("/api/presentation/media/".length));
    if (!mediaWhitelist.size) discoverRealScreenshots();
    const filePath = mediaWhitelist.get(key);
    if (!filePath || !existsSync6(filePath)) {
      sendJson3(res, 404, { error: "imagem n\xE3o encontrada" });
      return true;
    }
    try {
      const buf = readFileSync9(filePath);
      const ext = filePath.toLowerCase().endsWith(".png") ? "image/png" : "image/jpeg";
      res.writeHead(200, {
        "Content-Type": ext,
        "Content-Length": String(buf.length),
        "Cache-Control": "no-cache"
      });
      res.end(buf);
    } catch {
      sendJson3(res, 500, { error: "erro ao ler imagem" });
    }
    return true;
  }
  if (path === "/api/presentation/question") {
    if (method !== "POST") {
      res.setHeader("Allow", "POST");
      sendJson3(res, 405, { error: "m\xE9todo n\xE3o permitido" });
      return true;
    }
    void readJsonBody(req).then((body2) => {
      const deck = buildPresentationDeck(deps);
      const action = typeof body2?.action === "string" ? body2.action : "";
      if (action === "approve") {
        isPendingReview = false;
        founderLog.push({ at: Date.now(), type: "approve", text: String(body2?.note || "Entrega aprovada na Reuni\xE3o 3D") });
        sendJson3(res, 200, {
          ok: true,
          celebration: true,
          turns: [
            {
              agentKey: "vicente",
              name: "Vicente",
              text: "Entrega aprovada pelo fundador! Parab\xE9ns a toda a equipe do andar, trabalho impec\xE1vel!"
            },
            {
              agentKey: "release",
              name: "Release",
              text: "Aprova\xE7\xE3o registrada! J\xE1 estamos prontos para avan\xE7ar para a pr\xF3xima etapa quando voc\xEA mandar."
            }
          ]
        });
        return;
      }
      if (action === "changes") {
        const note = String(body2?.note || "Ajuste solicitado pelo fundador").trim();
        founderLog.push({ at: Date.now(), type: "changes", text: note });
        sendJson3(res, 200, {
          ok: true,
          celebration: false,
          turns: [
            {
              agentKey: "user",
              name: "Usu\xE1rio",
              text: `Recebido! Registrei o pedido de ajuste: "${note.slice(0, 75)}".`
            },
            {
              agentKey: "dev",
              name: "Dev",
              text: "Beleza, voltando pra esta\xE7\xE3o assim que encerrarmos a apresenta\xE7\xE3o para corrigir isso na hora!"
            }
          ]
        });
        return;
      }
      const question = String(body2?.question || "").trim();
      const slideTitle = String(body2?.slideTitle || "Apresenta\xE7\xE3o").trim();
      if (!question) {
        sendJson3(res, 400, { error: "question obrigat\xF3rio" });
        return;
      }
      founderLog.push({ at: Date.now(), type: "question", text: question });
      void generateMeetingAnswer(question, slideTitle, deck).then((turns) => {
        sendJson3(res, 200, { ok: true, turns });
      });
    }).catch((err) => {
      sendJson3(res, 400, { error: err instanceof Error ? err.message : "erro inv\xE1lido" });
    });
    return true;
  }
  return false;
}

