    log.info(tr("   Codex: {0} conta(s), {1} sess\xE3o(\xF5es) aberta(s).", [codexAccounts.length, open3]));
    for (const a of codexAccounts) {
      log.info(tr("   Conta {0} do Codex ({1}): uso: {2} \xB7 {3}", [a.detected.short, a.id, accounts.usageView(a.id).status, a.detected.configDir]));
    }
